#pragma once

#include <atomic>

enum class CombatMod : unsigned {
    Health = 1u << 0,
    Magazine = 1u << 1,
    Reserve = 1u << 2,
    Secondary = 1u << 3,
    Grenades = 1u << 4,
    RapidFire = 1u << 5,
    ArcCooling = 1u << 6,
    SniperFocus = 1u << 7,
    LongerJump = 1u << 8,
};

inline std::atomic<unsigned> rfom_combat_mods{0};

inline bool combat_mod_enabled(CombatMod mod)
{
    return (rfom_combat_mods.load(std::memory_order_relaxed) & static_cast<unsigned>(mod)) != 0;
}

